#include <runtime/events/engine.hpp>
namespace rebuntu::events {void Engine::add_rule(Rule r){rules_.push_back(std::move(r));}std::vector<Violation>Engine::ingest(Event e){auto now=e.at;auto sig=e.type+"\0"+e.subject+"\0"+e.message;auto it=dedupe_.find(sig);if(it!=dedupe_.end()&&now-it->second<std::chrono::seconds(1))return{};dedupe_[sig]=now;events_.push_back(e);while(events_.size()>capacity_)events_.pop_front();Assertion a{e.id,e.subject,e.type,e.message,1.0};assertions_.push_back(a);std::vector<Violation>v;for(auto&r:rules_)if(r.condition.matches&&r.condition.matches(a))v.push_back({r.id,a.id,r.alert_title});return v;}std::vector<Event>Engine::recent()const{return{events_.begin(),events_.end()};}std::vector<Event>Engine::correlate(std::string_view s,std::chrono::seconds w)const{std::vector<Event>o;if(events_.empty())return o;auto end=events_.back().at;for(auto&e:events_)if(e.subject==s&&end-e.at<=w)o.push_back(e);return o;}}
